import { useEffect, useState } from 'react';

// Ramadan 1448: the first night is expected at Maghrib on Sunday 7 February 2027,
// the first fast on Monday 8 February, Eid al-Fitr about Tuesday 9 March, all by
// the sighting of the moon. Maghrib is shown as 18:00 in the visitor's own time
// zone; the app counts to the exact sunset of their city.
// Change these dates (and the copy in locales/<lang>/ramadan.json) for next year.
export const FIRST_NIGHT = () => new Date(2027, 1, 7, 18, 0, 0);
export const EID = () => new Date(2027, 2, 9, 6, 0, 0);
// The bar and the home card show from now until the morning of Eid.
export const inSeason = (now = Date.now()) => now < EID().getTime();
export const hasBegun = (now = Date.now()) => now >= FIRST_NIGHT().getTime();

const SYNODIC = 29.530588853;
const NEW_MOON_REF = Date.UTC(2000, 0, 6, 18, 14);
// 0 = new moon, 0.5 = full moon.
export const moonPhase = (now = Date.now()) => ((((now - NEW_MOON_REF) / 864e5) % SYNODIC) + SYNODIC) % SYNODIC / SYNODIC;
export const moonIllumination = (ph) => Math.round(((1 - Math.cos(ph * 2 * Math.PI)) / 2) * 100);
export const moonPhaseKey = (ph) => {
    const age = ph * SYNODIC;
    const names = [[1.5, 'new'], [6.9, 'waxingCrescent'], [8.4, 'firstQuarter'], [13.8, 'waxingGibbous'], [15.8, 'full'],
        [21.1, 'waningGibbous'], [22.6, 'lastQuarter'], [28, 'waningCrescent'], [30, 'new']];
    return names.find(([a]) => age < a)[1];
};

export function splitDuration(ms) {
    let r = Math.max(0, ms);
    const days = Math.floor(r / 864e5); r -= days * 864e5;
    const hours = Math.floor(r / 36e5); r -= hours * 36e5;
    const minutes = Math.floor(r / 6e4); r -= minutes * 6e4;
    return { days, hours, minutes, seconds: Math.floor(r / 1000) };
}

// Ticks once a second; null on the very first render so server-built HTML and the
// first client render agree.
export function useRamadanCountdown() {
    const [now, setNow] = useState(null);
    useEffect(() => {
        setNow(Date.now());
        const id = setInterval(() => setNow(Date.now()), 1000);
        return () => clearInterval(id);
    }, []);
    if (now == null) return null;
    return { now, ...splitDuration(FIRST_NIGHT().getTime() - now), begun: hasBegun(now) };
}

export const pad2 = (n) => String(n).padStart(2, '0');
