import React, { useEffect, useRef } from 'react';
import { Box } from '@mui/material';

// The moon in a given phase (0 new … 0.5 full … 1 new), with earthshine and a halo.
export function drawMoon(ctx, W, ph, { halo = true } = {}) {
    ctx.clearRect(0, 0, W, W);
    const c = W / 2, R = W * (halo ? 0.34 : 0.46);
    if (halo) {
        const g = ctx.createRadialGradient(c, c, R * 0.9, c, c, W / 2);
        g.addColorStop(0, 'rgba(232,196,106,.22)'); g.addColorStop(1, 'rgba(232,196,106,0)');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, W);
    }
    ctx.fillStyle = '#1b2147'; ctx.beginPath(); ctx.arc(c, c, R, 0, 6.283); ctx.fill();
    const waxing = ph < 0.5, k = Math.cos(ph * 2 * Math.PI);
    const lit = ctx.createRadialGradient(c - R * 0.3, c - R * 0.3, R * 0.1, c, c, R);
    lit.addColorStop(0, '#fff8e0'); lit.addColorStop(0.6, '#f3dc9a'); lit.addColorStop(1, '#c9a14e');
    ctx.fillStyle = lit; ctx.beginPath();
    ctx.arc(c, c, R, -Math.PI / 2, Math.PI / 2, !waxing);
    ctx.ellipse(c, c, Math.abs(k) * R, R, 0, Math.PI / 2, -Math.PI / 2, (k > 0) === waxing);
    ctx.closePath(); ctx.fill();
    ctx.globalCompositeOperation = 'source-atop'; ctx.fillStyle = 'rgba(120,96,50,.18)';
    [[-0.25, -0.2, 0.22], [0.15, 0.1, 0.16], [-0.05, 0.35, 0.12], [0.3, -0.3, 0.1]].forEach(([dx, dy, r]) => {
        ctx.beginPath(); ctx.arc(c + dx * R, c + dy * R, r * R, 0, 6.283); ctx.fill();
    });
    ctx.globalCompositeOperation = 'source-over';
}

export default function MoonCanvas({ phase, label, halo = true, sx }) {
    const ref = useRef(null);
    useEffect(() => {
        const el = ref.current;
        if (!el) return undefined;
        const paint = () => {
            const dpr = Math.min(window.devicePixelRatio || 1, 2), W = el.clientWidth || 1;
            if (el.width !== W * dpr || el.height !== W * dpr) { el.width = W * dpr; el.height = W * dpr; }
            const ctx = el.getContext('2d');
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            drawMoon(ctx, W, phase, { halo });
        };
        paint();
        const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(paint) : null;
        ro?.observe(el);
        return () => ro?.disconnect();
    }, [phase, halo]);
    return <Box component="canvas" ref={ref} role="img" aria-label={label} sx={{ display: 'block', width: '100%', aspectRatio: '1', ...sx }} />;
}
